related_terms.medium_def:
A man living at the time of Exile and Return, only mentioned at Neh.3.10; 
only referred to as Harumaph (חֲרוּמַף); 
father of Jedaiah. § father of Jedaiah, one of the builders of the wall in Nehemiah's time

A king of Judah living at the time of Divided Monarchy, first mentioned at 2Ki.14.21; 
referred to as Uzziah (עֻזִּיָּהוּ), or Azariah (עֲזַרְיָה), or Azariah (עֲזַרְיָ֫הוּ), or Uzziah (KJV= Ozias) (Ὀζίας); 
a son of Amaziah and Jecoliah; 
husband of Jerusha; 
father of Jotham.

Aaron's uncle from the tribe of Levi living at the time of Egypt and Wilderness, first mentioned at Exo.6.18; 
referred to as Uzziel (עֻזִּיאֵל), or Uzzielite (עׇזִּיאֵלִי); 
son of Kohath; 
a brother of Amram, Izhar and Hebron; 
father of Mishael, Elizaphan, Sithri, Micah and Isshiah.

A man living at the time of United Monarchy, first mentioned at 2Sa.6.3; 
referred to as Uzzah or Uzzah (עֻזָּא), or Perez-uzzah (NIV= Perez Uzzah) (פֶּרֶץ עֻזָּא); 
son of Abinadab; 
a brother of Eleazar and Ahio.

A High Priest from the tribe of Levi living at the time of Divided Monarchy, first mentioned at 1Ch.6.5; 
only referred to as Uzzi (עֻזִּי); 
a son of Bukki; 
father of Zerahiah.

A man from the tribe of Levi living at the time of Egypt and Wilderness, first mentioned at 1Ch.24.26; 
only referred to as Jaaziah (יַעֲזִיָּ֫הוּ); 
son of Merari; 
a brother of Mahli and Mushi; 
father of Beno, Shoham, Zaccur and Ibri. § a Levite, apparently the 3rd son or a descendant of Merari

A man from the tribe of Issachar living at the time of Egypt and Wilderness, first mentioned at 1Ch.7.2; 
only referred to as Uzzi (עֻזִּי); 
son of Tola; 
a brother of Rephaiah, Jeriel, Jahmai, Ibsam and Shemuel; 
father of Izrahiah.

Aaron's uncle from the tribe of Levi living at the time of Egypt and Wilderness, first mentioned at Exo.6.18; 
referred to as Uzziel (עֻזִּיאֵל), or Uzzielite (עׇזִּיאֵלִי); 
son of Kohath; 
a brother of Amram, Izhar and Hebron; 
father of Mishael, Elizaphan, Sithri, Micah and Isshiah. § Uzzielites, of Uzziel "my strength is God"
descendants of Uzziel

A man from the tribe of Benjamin living at the time of Divided Monarchy, first mentioned at 1Ch.8.36; 
only referred to as Azmaveth (עַזְמָ֫וֶת); 
son of Jehoaddah; 
a brother of Alemeth and Zimri.

A man from the tribe of Levi living at the time of Divided Monarchy, only mentioned at 1Ch.6.29; 
only referred to as Uzzah (עֻזָּה); 
a son of Shimei; 
father of Shimea. § a Merarite Levite

A man from the tribe of Benjamin living before Israel's Monarchy, only mentioned at 1Ch.8.7; 
only referred to as Uzza (עֻזָּא); 
son of Ehud; 
a brother of Naaman, Ahijah, Gera and Ahihud. § a Merarite Levite

A man living at the time of Exile and Return, only mentioned at Neh.3.16; 
only referred to as Azbuk (עַזְבּוּק); 
father of Nehemiah. § father of Nehemiah, leader of half the district of Beth Zur, and a repairer of the walls of Jerusalem under another Nehemiah

A man from the tribe of Reuben living at the time of Divided Monarchy, only mentioned at 1Ch.5.8; 
only referred to as Azaz (עָזָז); 
a son of Shema; 
father of Bela. § a Reubenite, father of Bela

A man living at the time of Divided Monarchy, only mentioned at 1Ch.27.20; 
only referred to as Azaziah (עֲזַזְיָ֫הוּ); 
father of Hoshea.

A man from the tribe of Benjamin living at the time of Egypt and Wilderness, only mentioned at 1Ch.7.7; 
only referred to as Uzzi (עֻזִּי); 
son of Bela; 
a brother of Ard, Naaman, Ezbon, Uzziel, Jerimoth, Iri, Addar, Gera, Abihud, Abishua and Ahoah.

A man living at the time of Exile and Return, only mentioned at 1Ch.9.8; 
only referred to as Uzzi (עֻזִּי); 
a son of Michri; 
father of Elah.

A man living at the time of Exile and Return, only mentioned at Neh.11.22; 
only referred to as Uzzi (עֻזִּי); 
a son of Bani.

A man from the tribe of Simeon(?) living at the time of Divided Monarchy, only mentioned at 1Ch.4.42; 
only referred to as Uzziel (עֻזִּיאֵל); 
son of Ishi; 
a brother of Pelatiah, Neariah and Rephaiah.

A man from the tribe of Benjamin living at the time of Egypt and Wilderness, only mentioned at 1Ch.7.7; 
only referred to as Uzziel (עֻזִּיאֵל); 
son of Bela; 
a brother of Ard, Naaman, Ezbon, Uzzi, Jerimoth, Iri, Addar, Gera, Abihud, Abishua and Ahoah.

A man from the tribe of Levi living at the time of Divided Monarchy, first mentioned at 1Ch.25.4; 
referred to as Uzziel (עֻזִּיאֵל), or Azarel (KJV= Azareel) (עֲזַרְאֵל); 
son of Heman; 
a brother of Bukkiah, Mattaniah, Shebuel, Jerimoth, Hananiah, Hanani, Eliathah, Giddalti, Romamti-ezer, Joshbekashah, Mallothi, Hothir and Mahazioth.

A man from the tribe of Levi living at the time of Divided Monarchy, only mentioned at 2Ch.29.14; 
only referred to as Uzziel (עֻזִּיאֵל); 
son of Jeduthun; 
a brother of Shemaiah.

A man living at the time of Exile and Return, only mentioned at Neh.3.8; 
only referred to as Uzziel (עֻזִּיאֵל); 
a son of Harhaiah.

A man from the tribe of Levi living at the time of Divided Monarchy, first mentioned at 1Ch.6.24; 
referred to as Uzziah (עֻזִּיָּהוּ), or Azariah (עֲזַרְיָ֫הוּ); 
a son of Uriel; 
father of Shaul.

A man living at the time of Divided Monarchy, only mentioned at 1Ch.27.25; 
only referred to as Uzziah (עֻזִּיָּהוּ); 
father of Jonathan.

A man living at the time of Exile and Return, only mentioned at Neh.11.4; 
only referred to as Uzziah (עֻזִּיָּהוּ); 
a son of Zechariah; 
father of Athaiah.

A man living at the time of Divided Monarchy, only mentioned at 1Ch.12.3; 
only referred to as Azmaveth (עַזְמָ֫וֶת); 
father of Jeziel, Pelet.

A man living at the time of Divided Monarchy, only mentioned at 1Ch.27.25; 
only referred to as Azmaveth (עַזְמָ֫וֶת); 
a son of Adiel.

A man living at the time of Egypt and Wilderness, only mentioned at Num.34.26; 
only referred to as Azzan (עַזָּן); 
father of Paltiel. § father of Paltiel prince of the tribe of Issachar who represented his tribe in the division of the promised land

A man living at the time of Divided Monarchy, first mentioned at 2Ch.15.1; 
only referred to as Oded (עֹדֵד); 
father of Azariah.

A High Priest living at the time of United Monarchy, first mentioned at 1Sa.1.3; 
only referred to as Eli (עֵלִי); 
father of Hophni, Phinehas. § descendant of Aaron through Ithamar and high priest and judge of Israel when Samuel entered service as a child

A location first mentioned at Num.34.4; 
only referred to as Akrabbim (עַקְרַבִּים). § a pass on the southern border of Palestine
scorpion-pass; ascent of Akrabbim

A man living at the time of the Patriarchs, first mentioned at Gen.36.23; 
referred to as Alvan or Alvan (עַלְיָן, עַלְוָן); 
son of Shobal; 
a brother of Manahath, Ebal, Shepho and Onam. § a Horite, son of Shobal

People from Aph(?) from the tribe of Judah, first mentioned at 1Ch.2.30; 
only referred to as Appaim (אַפַּיִם); 
descended from Nadab along with Seled; 
progenitors of Ishi. § a son of Nadab

A man of the Arabs living at the time of the Patriarchs, first mentioned at Gen.25.15; 
referred to as Hadad (חֲדַד), or Hadad (KJV= Hadar, in Ben Chaim) (חֲדַר); 
son of Ishmael; 
a brother of Nebaioth, Kedar, Adbeel, Mibsam, Mishma, Dumah, Massa, Tema, Jetur, Naphish, Kedemah and Mahalath. § a son of Ishmael

A man of the Arabs living at the time of the Patriarchs, first mentioned at Gen.25.15; 
referred to as Hadad (חֲדַד), or Hadad (KJV= Hadar, in Ben Chaim) (חֲדַר); 
son of Ishmael; 
a brother of Nebaioth, Kedar, Adbeel, Mibsam, Mishma, Dumah, Massa, Tema, Jetur, Naphish, Kedemah and Mahalath. § an Edomite king
(scribal error for חֲדַד)
